        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, buflen = 0;
        private final InputStream in;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= buflen) {
                buflen = in.read(buffer);
                ptr = 0;
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = readByte(), x = 0;
            while (c <= ' ') c = readByte();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            do {
                x = (x << 3) + (x << 1) + (c & 15);
            } while ((c = readByte()) > ' ');
            return neg ? -x : x;
        }
    }

    static class Edge {
        int to, rev;
        Edge(int to, int rev) {
            this.to = to;
            this.rev = rev;
        }
    }

    static List<Edge>[] g;
    static int[] a;
    static int n, k;
    static int[] size;
    static int[] best;

    static void dfsSize(int u, int p) {
        size[u] = 1;
        for (Edge e : g[u]) {
            if (e.to == p) continue;
            dfsSize(e.to, u);
            size[u] += size[e.to];
        }
    }

    static int dfsBest(int u, int p, int limit) {
        int res = a[u];
        List<Integer> children = new ArrayList<>();
        for (Edge e : g[u]) {
            if (e.to == p) continue;
            children.add(e.to);
        }
        children.sort((x, y) -> best[y] - best[x]);
        int rem = limit - 1;
        for (int v : children) {
            if (rem <= 0) break;
            int take = Math.min(rem, size[v]);
            res = Math.max(res, dfsBest(v, u, take));
            rem -= take;
        }
        return res;
    }

