    static boolean isPossible(int x) {
        visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (a[i] >= x && !visited[i]) {
                int size = dfs(i, x);
                if (size >= k) {
                    return true;
                }
            }
        }
        return false;
    }

    static int dfs(int u, int x) {
        visited[u] = true;
        int size = 1;
        for (int v : adj[u]) {
            if (!visited[v] && a[v] >= x) {
