import java.io.*;
import java.util.*;

public class Main {
    static int n, k;
    static int[] a;
    static List<Integer>[] adj;
    static boolean[] visited;
    static int[] size;
    static int[] order;
    static int idx;

    static void dfs(int u, int p) {
        visited[u] = true;
        size[u] = 1;
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs(v, u);
            size[u] += size[v];
        }
    }

    static void dfs2(int u, int p) {
        order[idx++] = u;
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs2(v, u);
        }
    }

